mapper.insert:
INSERT INTO `${orderTable}` (
    username, status, total_yuan, remark


            `${col}`


    , created_at, updated_at
) VALUES (
    #{username}, #{status}, #{totalYuan}, #{remark}


            #{val}


    , #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT * FROM `${orderTable}`

    AND username=#{username}
    AND status=#{status}

ORDER BY id DESC

SELECT o.* FROM `${orderTable}` o
EXISTS (SELECT 1 FROM `${lineTable}` l JOIN `${itemTable}` p ON p.id=l.item_id WHERE l.order_id=o.id AND p.owner_username=#{ownerUsername}) AND o.status=#{status}
ORDER BY o.id DESC

mapper.update:
UPDATE `${orderTable}` SET status=#{status}
, tracking_no=#{trackingNo}
, pickup_code=#{pickupCode}
, shipped_at=#{shippedAt}
, updated_at=#{updatedAt}
WHERE id=#{id}

UPDATE `${orderTable}`
SET total_yuan=#{totalYuan}, discount_yuan=#{discountYuan}, pay_balance_yuan=#{payBalanceYuan},
    coupon_code=#{couponCode}, updated_at=#{updatedAt}
WHERE id=#{id}

UPDATE `${orderTable}`
SET total_yuan=#{totalYuan}, discount_yuan=#{discountYuan}, pay_balance_yuan=#{payBalanceYuan},
    updated_at=#{updatedAt}
WHERE id=#{id}
